    AND EFF_DATE <= #{effDate,jdbcType=TIMESTAMP}

mapper.select:
SELECT COUNT(1) FROM (
    SELECT
    REP_ID,
    REP_STATUS,
    rownum RN
    FROM REP_INFO_STATUS WHERE REP_ID = #{repId,jdbcType=VARCHAR} AND
    AND EFF_DATE <= #{effDate,jdbcType=TIMESTAMP}
    ORDER BY EFF_DATE DESC
) WHERE RN = 1 AND REP_STATUS = #{repStatus,jdbcType=VARCHAR}

